import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BkRhkvTH.js";const l=JSON.parse('{"title":"Users, Auth & API Keys","description":"","frontmatter":{},"headers":[],"relativePath":"api/users.md","filePath":"api/users.md","lastUpdated":1784213339000}'),r={name:"api/users.md"};function s(i,e,c,n,p,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="users-auth-api-keys" tabindex="-1">Users, Auth &amp; API Keys <a class="header-anchor" href="#users-auth-api-keys" aria-label="Permalink to &quot;Users, Auth &amp; API Keys&quot;">​</a></h1><h2 id="sign-in-api-auth" tabindex="-1">Sign-in - <code>/api/auth</code> <a class="header-anchor" href="#sign-in-api-auth" aria-label="Permalink to &quot;Sign-in - `/api/auth`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/auth/login/masterkey</code></td><td>Sign in with just the master key (no email). Returns a session token, or <code>RequiresTwoFactor: true</code> if 2FA is enabled.</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/login/enhanced</code></td><td>Sign in with email + master password, with 2FA/passkey support.</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/otp/send</code></td><td>Send an SMS OTP code (if SMS 2FA is configured).</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/otp/login</code></td><td>Complete sign-in with an OTP code.</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/otp/setup</code> / <code>/api/auth/otp/verify-setup</code></td><td>Enable SMS-based 2FA for the signed-in user.</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/otp/disable</code></td><td>Disable 2FA (requires master password + a valid code or backup code).</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/qr/generate-anonymous</code></td><td>Generate an anonymous QR code shown on a device that isn&#39;t signed in yet.</td></tr><tr><td><code>POST</code></td><td><code>/api/auth/qr/authenticate</code></td><td>A second device scans the QR and authenticates, signing the first device in.</td></tr><tr><td><code>DELETE</code></td><td><code>/api/auth/account</code></td><td>Permanently delete the signed-in user&#39;s account and all their data. Requires the master password.</td></tr></tbody></table><p>Every login response includes an <code>AuthResponseDto</code> with a session <code>Token</code> valid for 8 hours, used as <code>Authorization: Bearer &lt;token&gt;</code> on endpoints that decrypt or reveal secrets.</p><h2 id="api-keys-api-apikeys" tabindex="-1">API keys - <code>/api/apikeys</code> <a class="header-anchor" href="#api-keys-api-apikeys" aria-label="Permalink to &quot;API keys - `/api/apikeys`&quot;">​</a></h2><p>The credential mobile apps and the browser extension use instead of a full login session - see <a href="/PasswordManagerApp/guide/getting-started#getting-an-api-key-for-mobile-the-browser-extension">Getting Started</a> for the end-user flow.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/apikeys/issue</code></td><td>none (<code>[AllowAnonymous]</code>)</td><td>Issue a key from email + master password. Returns the plaintext key <strong>once</strong>.</td></tr><tr><td><code>GET</code></td><td><code>/api/apikeys</code></td><td>session</td><td>List the caller&#39;s keys. The <code>KeyHash</code> field is masked (<code>***</code>) - the plaintext is never retrievable again.</td></tr><tr><td><code>POST</code></td><td><code>/api/apikeys</code></td><td>session</td><td>Create a named key for the signed-in user.</td></tr><tr><td><code>DELETE</code></td><td><code>/api/apikeys/{keyId}</code></td><td>session</td><td>Revoke a key. Scoped to the caller - you cannot revoke another user&#39;s key by guessing its ID.</td></tr></tbody></table><p>Keys are stored <strong>hash-only</strong>; validation matches by hash, and revocation is a soft delete (<code>IsActive = false</code>) scoped to the owning user.</p><h2 id="user-profile-admin-api-userprofile" tabindex="-1">User profile &amp; admin - <code>/api/userprofile</code> <a class="header-anchor" href="#user-profile-admin-api-userprofile" aria-label="Permalink to &quot;User profile &amp; admin - `/api/userprofile`&quot;">​</a></h2><p>Admin-only (<code>[Authorize(Roles = &quot;Admin&quot;)]</code>) management of user accounts.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/userprofile</code></td><td>All users in the system.</td></tr><tr><td><code>GET</code></td><td><code>/api/userprofile/{id}</code></td><td>A user&#39;s profile details.</td></tr><tr><td><code>POST</code></td><td><code>/api/userprofile</code></td><td>Create a new user. Body: <code>CreateUserProfileDto</code> (email, password, confirm password, name, master-password hint). Returns <code>201</code> with a <code>Location</code> header.</td></tr><tr><td><code>PUT</code></td><td><code>/api/userprofile/{id}</code></td><td>Update profile fields (email, name, hint). Body: <code>UpdateUserProfileDto</code>.</td></tr><tr><td><code>PUT</code></td><td><code>/api/userprofile/{id}/password</code></td><td>Change a user&#39;s master password. Body: <code>ChangePasswordDto</code> (current + new password).</td></tr><tr><td><code>PUT</code></td><td><code>/api/userprofile/{id}/deactivate</code></td><td>Deactivate an account (soft, reversible).</td></tr><tr><td><code>PUT</code></td><td><code>/api/userprofile/{id}/reactivate</code></td><td>Reactivate a deactivated account.</td></tr><tr><td><code>DELETE</code></td><td><code>/api/userprofile/{id}</code></td><td>Permanently delete a user account.</td></tr></tbody></table>',11)])])}const f=t(r,[["render",s]]);export{l as __pageData,f as default};
